// RecordServiceServer is the server API for RecordService service.
// All implementations must embed UnimplementedRecordServiceServer
// for forward compatibility.
//
// RecordService is the gRPC API served by `cbt serve`. RPCs are added here and
// registered in cmd/serve.go.
//
// Every record type and the cognitive bias vocabulary live on a single service
// rather than one service per entity: the client wrapper and the interceptor
// wiring would otherwise be duplicated for no gain, and listing across both
// record types needs a single endpoint anyway.
type RecordServiceServer interface {
	// ListThoughtRecords returns the user's thought records, most recent event
	// first. Filtering by challenged = false yields the day's work queue.
	ListThoughtRecords(context.Context, *ListThoughtRecordsRequest) (*ListThoughtRecordsResponse, error)
	// CreateThoughtRecord creates a record. Only the event is required: a record
	// is routinely opened in the moment and completed later.
	CreateThoughtRecord(context.Context, *CreateThoughtRecordRequest) (*ThoughtRecord, error)
	// GetThoughtRecord returns a single record by identifier.
	GetThoughtRecord(context.Context, *GetThoughtRecordRequest) (*ThoughtRecord, error)
	// UpdateThoughtRecord changes the free text columns of a record. Fields left
	// unset keep their current value.
	UpdateThoughtRecord(context.Context, *UpdateThoughtRecordRequest) (*ThoughtRecord, error)
	// ChallengeThoughtRecord records the second sitting: the alternative view
	// and the evidence for it, the re-rating of each feeling, and the biases
	// identified in each thought and how much it is still believed.
	// It stamps challenged_at so the record leaves the unchallenged queue.
	ChallengeThoughtRecord(context.Context, *ChallengeThoughtRecordRequest) (*ThoughtRecord, error)
	// DeleteThoughtRecord removes a record along with its thoughts and feelings.
	DeleteThoughtRecord(context.Context, *DeleteThoughtRecordRequest) (*emptypb.Empty, error)
	// AddThought attaches a further negative thought to a record.
	AddThought(context.Context, *AddThoughtRequest) (*ThoughtRecord, error)
	// UpdateThought changes the wording of a thought and, optionally, the biases
	// attached to it.
	UpdateThought(context.Context, *UpdateThoughtRequest) (*ThoughtRecord, error)
	// SetHotThought marks a thought as the strongest of its record, clearing the
	// flag from its siblings.
	SetHotThought(context.Context, *SetHotThoughtRequest) (*ThoughtRecord, error)
	// SetThoughtFactual records whether a thought was judged an accurate reading
	// of the situation. Marking one factual while it carries a bias is rejected.
	SetThoughtFactual(context.Context, *SetThoughtFactualRequest) (*ThoughtRecord, error)
	// SetThoughtEvidence records what supports a thought. It can be called at
	// any time and does not mark the record as challenged.
	SetThoughtEvidence(context.Context, *SetThoughtEvidenceRequest) (*ThoughtRecord, error)
	// DeleteThought removes a thought from its record.
	DeleteThought(context.Context, *DeleteThoughtRequest) (*ThoughtRecord, error)
	// AddFeeling attaches a rated feeling to a thought record.
	AddFeeling(context.Context, *AddFeelingRequest) (*ThoughtRecord, error)
	// AddMapFeeling attaches a rated feeling to a map of worry.
	AddMapFeeling(context.Context, *AddMapFeelingRequest) (*MapOfWorry, error)
	// DeleteFeeling removes a feeling from whichever record it belongs to.
	DeleteFeeling(context.Context, *DeleteFeelingRequest) (*emptypb.Empty, error)
	// ListMapsOfWorry returns the user's maps of worry, most recent event first.
	ListMapsOfWorry(context.Context, *ListMapsOfWorryRequest) (*ListMapsOfWorryResponse, error)
	// CreateMapOfWorry creates a map. Setting derived_from_id marks it as an
	// alternative reworking of an existing map, to be read alongside it.
	CreateMapOfWorry(context.Context, *CreateMapOfWorryRequest) (*MapOfWorry, error)
	// GetMapOfWorry returns a single map together with the map it was derived
	// from and any alternatives derived from it.
	GetMapOfWorry(context.Context, *GetMapOfWorryRequest) (*GetMapOfWorryResponse, error)
	// UpdateMapOfWorry changes the free text columns of a map.
	UpdateMapOfWorry(context.Context, *UpdateMapOfWorryRequest) (*MapOfWorry, error)
	// DeleteMapOfWorry removes a map along with its feelings. A map with
	// alternatives derived from it is rejected.
	DeleteMapOfWorry(context.Context, *DeleteMapOfWorryRequest) (*emptypb.Empty, error)
	// ListBehaviouralExperiments returns the user's behavioural experiments,
	// most recent first. Filtering by completed = false yields the experiments
	// still to be carried out.
	ListBehaviouralExperiments(context.Context, *ListBehaviouralExperimentsRequest) (*ListBehaviouralExperimentsResponse, error)
	// CreateBehaviouralExperiment creates an experiment. Only the plan is
	// required; feelings given here are the ones predicted.
	CreateBehaviouralExperiment(context.Context, *CreateBehaviouralExperimentRequest) (*BehaviouralExperiment, error)
	// GetBehaviouralExperiment returns a single experiment by identifier.
	GetBehaviouralExperiment(context.Context, *GetBehaviouralExperimentRequest) (*BehaviouralExperiment, error)
	// UpdateBehaviouralExperiment changes the free text columns of an
	// experiment without marking it completed. Fields left unset keep their
	// current value.
	UpdateBehaviouralExperiment(context.Context, *UpdateBehaviouralExperimentRequest) (*BehaviouralExperiment, error)
	// CompleteBehaviouralExperiment records the second sitting: what actually
	// happened, what was learned, how to build on it, and how each feeling was
	// actually felt. It stamps completed_at so the experiment leaves the queue.
	CompleteBehaviouralExperiment(context.Context, *CompleteBehaviouralExperimentRequest) (*BehaviouralExperiment, error)
	// DeleteBehaviouralExperiment removes an experiment along with its
	// feelings.
	DeleteBehaviouralExperiment(context.Context, *DeleteBehaviouralExperimentRequest) (*emptypb.Empty, error)
	// AddExperimentFeeling attaches a predicted feeling to an experiment.
	AddExperimentFeeling(context.Context, *AddExperimentFeelingRequest) (*BehaviouralExperiment, error)
	// ListPositiveDataLogs returns the user's positive data logs, the most
	// recently added to first.
	ListPositiveDataLogs(context.Context, *ListPositiveDataLogsRequest) (*ListPositiveDataLogsResponse, error)
	// CreatePositiveDataLog creates a log. Only the belief is required.
	CreatePositiveDataLog(context.Context, *CreatePositiveDataLogRequest) (*PositiveDataLog, error)
	// GetPositiveDataLog returns a single log by identifier.
	GetPositiveDataLog(context.Context, *GetPositiveDataLogRequest) (*PositiveDataLog, error)
	// UpdatePositiveDataLog rewords the beliefs of a log. Ratings are not
	// changed here; RateBeliefs appends one.
	UpdatePositiveDataLog(context.Context, *UpdatePositiveDataLogRequest) (*PositiveDataLog, error)
	// DeletePositiveDataLog removes a log along with its evidence and ratings.
	DeletePositiveDataLog(context.Context, *DeletePositiveDataLogRequest) (*emptypb.Empty, error)
	// AddDataLogEvidence appends a row of evidence to a log.
	AddDataLogEvidence(context.Context, *AddDataLogEvidenceRequest) (*PositiveDataLog, error)
	// DeleteDataLogEvidence removes a row of evidence and returns its log.
	DeleteDataLogEvidence(context.Context, *DeleteDataLogEvidenceRequest) (*PositiveDataLog, error)
	// RateBeliefs appends a rating of both beliefs to a log, keeping the
	// earlier ones.
	RateBeliefs(context.Context, *RateBeliefsRequest) (*PositiveDataLog, error)
	// ListFormulations returns the user's formulations, the most recently
	// changed first.
	ListFormulations(context.Context, *ListFormulationsRequest) (*ListFormulationsResponse, error)
	// CreateFormulation creates a formulation. Any column may be left blank,
	// but not all of them.
	CreateFormulation(context.Context, *CreateFormulationRequest) (*Formulation, error)
	// GetFormulation returns a single formulation by identifier.
	GetFormulation(context.Context, *GetFormulationRequest) (*Formulation, error)
	// UpdateFormulation changes the columns of a formulation.
	UpdateFormulation(context.Context, *UpdateFormulationRequest) (*Formulation, error)
	// DeleteFormulation removes a formulation.
	DeleteFormulation(context.Context, *DeleteFormulationRequest) (*emptypb.Empty, error)
	// ListBiases returns the user's cognitive bias vocabulary, ordered by name.
	ListBiases(context.Context, *ListBiasesRequest) (*ListBiasesResponse, error)
	// CreateBias adds a user defined bias alongside the seeded ones.
	CreateBias(context.Context, *CreateBiasRequest) (*CognitiveBias, error)
	// RenameBias renames a user defined bias. Builtin biases are rejected.
	RenameBias(context.Context, *RenameBiasRequest) (*CognitiveBias, error)
	// DeleteBias removes a user defined bias that is no longer in use.
	DeleteBias(context.Context, *DeleteBiasRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedRecordServiceServer()
}

